import { readFileSync } from "node:fs";
import { resolve } from "node:path";
const ASSETS_ROOT = resolve(process.cwd(), "test/assets");
export function loadAssetText(filename) {
    return readFileSync(resolve(ASSETS_ROOT, filename), "utf8");
}
export function loadAssetJson(filename) {
    return JSON.parse(loadAssetText(filename));
}
